if(!exists('rating_migration_backtest',mode='function'))library(creditratingsystem)
close<-function(a,b,tol=1e-12)stopifnot(max(abs(unlist(a)-unlist(b)))<tol)
d<-list(model_id='migration',model_version='1',parameter_version='1',data_fingerprint='synthetic-transitions',population_id='rated',split_id='holdout',prediction_origin='HOLDOUT',evaluation_cutoff='2021-01-01',target=list(event='default',horizon=30,time_unit='days',probability_measure='PHYSICAL',conditioning='origin_state'));rows<-lapply(0:3,function(i)list(prediction_id=as.character(i),entity_id=paste0('e',i),cluster_id=paste0('g',i),segment='all',as_of='2020-01-01',forecast_known_at='2020-01-01',horizon_end='2020-01-31',model_id='migration',model_version='1',parameter_version='1',outcome_known_at='2020-02-01',scale_id='grades',scale_version='1',origin_state=c('A','A','B','D')[i+1],destination_state=c('A','D','A','D')[i+1],observation_status='OBSERVED',state_observed_at='2020-01-31'));P<-rbind(c(.7,.2,.1,0),c(.1,.7,.2,0),c(0,0,1,0),c(0,0,0,1));contract<-list(scale_id='grades',scale_version='1',reference='frozen grades/default/exit',known_at='2019-01-01',default_states=list('D'),cure_states=list(),exit_states=list('X'),absorbing_states=list('D','X'));states<-c('A','B','D','X')
r<-rating_migration_backtest(rows,P,states,contract,d,'none')$value;close(r$metrics$overall$brier,.705);close(r$metrics$overall$log_loss,(-log(.7)-2*log(.1))/4);close(r$metrics$by_origin[[1]]$residuals,c(-.4,-.4,.8,0));close(r$metrics$by_origin[[1]]$expected_counts,c(1.4,.4,.2,0));stopifnot(r$metrics$by_origin[[4]]$applicability=='NOT_APPLICABLE',is.null(r$metrics$by_origin[[4]]$observed_probabilities));matrices<-lapply(seq_along(rows),function(i)lapply(seq_len(4),function(j)as.list(P[j,])));stopifnot(identical(rating_migration_backtest(rows,matrices,states,contract,d,'none')$value,r))
stopifnot(identical(rating_migration_backtest(rows,rep(list(P),length(rows)),states,contract,d,'none')$value,r))
bad<-rows;bad[[1]]$observation_status<-'CENSORED';bad[[1]]$destination_state<-NULL;bad[[4]]$destination_state<-'A';r<-rating_migration_backtest(bad,P,states,contract,d,'cluster_bootstrap',cluster_resamples=list(rep('g0',4),c('g1','g1','g2','g2')))$value;stopifnot(r$coverage$excluded_count==2,r$coverage$exclusion_counts$OBSERVED_ABSORBING_STATE_VIOLATION==1,r$uncertainty$intervals$brier$reason=='NON_ESTIMABLE_RESAMPLE')
P[1,]<-c(1,0,0,0);r<-rating_migration_backtest(rows,P,states,contract,d,'none')$value;stopifnot(r$metrics$overall$log_loss_status=='INFINITE',is.null(r$metrics$overall$log_loss));rows[[2]]$state_observed_at<-'2020-01-15';stopifnot(rating_migration_backtest(rows,P,states,contract,d,'none')$value$coverage$included_count==4);contract$absorbing_states<-list('X');stopifnot(rating_migration_backtest(rows,P,states,contract,d,'none')$value$coverage$exclusion_counts$ENDPOINT_STATE_NOT_OBSERVED==1)
